CREATE TABLE IF NOT EXISTS "EquipmentLog" (
    equip_code TEXT,
    reason TEXT
);

CREATE TABLE EquipmentLog (equip_code TEXT, reason TEXT);
INSERT INTO EquipmentLog (equip_code, reason)
SELECT e."EQUIP_CODE", 'Low EER and High Maintenance Cost'
FROM "Equipment" e
JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
WHERE (CAST(et."type_indices" ->> 'performance_score' AS numeric) + e."RELIAB_IDX") / 2 * (1 - CAST(et."type_indices" ->> 'environmental_impact_idx' AS numeric) / 100) < 40;

